class Solution { public String freqAlphabets(String s){StringBuilder answer=new StringBuilder();for(int i=0;i<s.length();){int value;if(i+2<s.length()&&s.charAt(i+2)=='#'){value=(s.charAt(i)-'0')*10+s.charAt(i+1)-'0';i+=3;}else{value=s.charAt(i)-'0';i++;}answer.append((char)('a'+value-1));}return answer.toString();} }
